    -d '{
        "model": "gemini-2.5-flash-preview-tts",
        "input": "Say the following: WOOHOO This is so much fun!.",
        "response_modalities": ["AUDIO"],
        "generation_config": {
            "speech_config": {
                "language": "en-us",
