      -H "Content-Type: application/json" \
      -H "Authorization: Bearer $GEMINI_API_KEY" \
      -d '{
        "model": "gemini-3-flash-preview",
        "reasoning_effort": "low",
        "messages": [
          {
            "role": "user",
            "content": "Explain to me how AI works"
          }
        ]
