        operation: operation,
      });
    }

    // Download the video.
    ai.files.download({
        file: operation.response.generatedVideos[0].video,
        downloadPath: "veo3_with_image_input.mp4",
    });
    console.log(`Generated video saved to veo3_with_image_input.mp4`);

