            type: Type.OBJECT,
            properties: {
              summary: {
                type: Type.STRING,
                description: "A concise summary of the audio content.",
              },
              segments: {
                type: Type.ARRAY,
                description: "List of transcribed segments with speaker and timestamp.",
                items: {
                  type: Type.OBJECT,
