    response = client.chat.completions.create(
      model="gemini-3-flash-preview",
      messages=[
        {
            "role": "system",
            "content": "You are a helpful assistant."
        },
        {   "role": "user",
            "content": "Hello!"
        }
      ],
      stream=True
    )

    for chunk in response:
        print(chunk.choices[0].delta)

### JavaScript

    import OpenAI from "openai";

