      "context"
      "fmt"
      "os"
      "google.golang.org/genai"
    )

    func main() {
      ctx := context.Background()
      client, err := genai.NewClient(ctx, nil)
      if err != nil {
          log.Fatal(err)
      }

      audioBytes, _ := os.ReadFile("/path/to/small-sample.mp3")

      parts := []*genai.Part{
          genai.NewPartFromText("Describe this audio clip"),
